#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common PolyBench-style definitions
#include "defines.hpp"

// include benchmark-specific definitions (NI, NJ, NK, NL, NM, DATA_TYPE, etc.)
#include "3mm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A, B, C, D with the same values as the original C kernel.
 *
 * C layout (row-major):
 *   A[ni][nk]
 *   B[nk][nj]
 *   C[nj][nm]
 *   D[nm][nl]
 *
 * Halide layout (column-major / x-fastest):
 *   A(k, i) => A[i][k]   -> Buffer A(nk, ni)
 *   B(j, k) => B[k][j]   -> Buffer B(nj, nk)
 *   C(m, j) => C[j][m]   -> Buffer C(nm, nj)
 *   D(l, m) => D[m][l]   -> Buffer D(nl, nm)
 */
static void init_array(int ni, int nj, int nk, int nl, int nm,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> D) {
    Var i("i"), j("j"), k("k"), l("l"), m("m");

    Func init_A("init_A"), init_B("init_B"), init_C("init_C"), init_D("init_D");

    // A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / (5*ni);
    // A has shape [ni][nk] in C => A(k, i) in Halide
    init_A(k, i) = cast<num_t>(((i * k + 1) % ni)) / cast<int>(5 * ni);

    // B[i][j] = (DATA_TYPE) ((i*(j+1)+2) % nj) / (5*nj);
    // B has shape [nk][nj] in C => B(j, k) in Halide
    init_B(j, k) = cast<num_t>(((k * (j + 1) + 2) % nj)) / cast<int>(5 * nj);

    // C[i][j] = (DATA_TYPE) (i*(j+3) % nl) / (5*nl);
    // C has shape [nj][nm] in C => C(m, j) in Halide
    init_C(m, j) = cast<num_t>(((j * (m + 3)) % nl)) / cast<int>(5 * nl);

    // D[i][j] = (DATA_TYPE) ((i*(j+2)+2) % nk) / (5*nk);
    // D has shape [nm][nl] in C => D(l, m) in Halide
    init_D(l, m) = cast<num_t>(((m * (l + 2) + 2) % nk)) / cast<int>(5 * nk);

    // Lightweight schedules for initialization: parallel over the slow dimension,
    // vectorize over the contiguous (x) dimension to improve bandwidth.
    Target init_target = get_jit_target_from_environment();
    const int vec_width = natural_vector_size(type_of<num_t>(), init_target);

    init_A.compute_root()
          .parallel(i)
          .vectorize(k, vec_width);

    init_B.compute_root()
          .parallel(k)
          .vectorize(j, vec_width);

    init_C.compute_root()
          .parallel(j)
          .vectorize(m, vec_width);

    init_D.compute_root()
          .parallel(m)
          .vectorize(l, vec_width);

    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes from 3mm.hpp
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;
    int nm = NM;

    // Allocate Buffers corresponding to the original C arrays.
    //
    // C layout: A[ni][nk] -> Halide: A(nk, ni)  (x=k/col, y=i/row)
    //           B[nk][nj] -> B(nj, nk)
    //           C[nj][nm] -> C(nm, nj)
    //           D[nm][nl] -> D(nl, nm)
    //           G[ni][nl] -> G(nl, ni)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nm, nj);
    Halide::Buffer<num_t, 2> D(nl, nm);
    Halide::Buffer<num_t, 2> G(nl, ni);  // final result

    // Initialize input matrices A, B, C, D.
    init_array(ni, nj, nk, nl, nm, A, B, C, D);

    // Create ImageParams for the input matrices so that the Halide
    // pipeline can be compiled independently of specific Buffers.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // Vars and reduction domains.
    Var i("i"), j("j"), l("l");
    RDom rAB(0, nk, "rAB");  // reduction over k for E = A * B
    RDom rCD(0, nm, "rCD");  // reduction over k for F = C * D
    RDom rEF(0, nj, "rEF");  // reduction over k for G = E * F

    // Define Funcs for the three matrix multiplications.
    //
    // 1) E := A * B
    // C: E[ni][nj] = sum_{k=0..nk-1} A[i][k] * B[k][j]
    // Halide: E(j, i)  (x=j, y=i)
    Func E("E");
    E(j, i) = cast<num_t>(0);
    E(j, i) += A_param(rAB, i) * B_param(j, rAB);

    // 2) F := C * D
    // C: F[nj][nl] = sum_{k=0..nm-1} C[i][k] * D[k][j]
    // Halide: F(l, j)  (x=l, y=j)
    Func F("F");
    F(l, j) = cast<num_t>(0);
    F(l, j) += C_param(rCD, j) * D_param(l, rCD);

    // 3) G := E * F
    // C: G[ni][nl] = sum_{k=0..nj-1} E[i][k] * F[k][j]
    // Halide: G_func(l, i)  (x=l, y=i)
    Func G_func("G");
    G_func(l, i) = cast<num_t>(0);
    G_func(l, i) += E(rEF, i) * F(l, rEF);

    // --------------------------------------------------------------------
    // Optimized schedule
    //
    // Goals:
    //   - Preserve original numerical results.
    //   - Parallelize across rows (outer dimensions) of each GEMM.
    //   - Vectorize across the innermost, contiguous x-dimension.
    //   - Reorder reduction loops to improve cache locality:
    //       * For E: make j (x) innermost so B(j, rAB) has contiguous
    //         access when traversing j inside a fixed rAB.
    //       * For F: make l (x) innermost for D(l, rCD).
    //       * For G: make l (x) innermost for F(l, rEF).
    //
    // We leave E, F, G computed at root (fully materialized), but the
    // schedule improves data locality and uses multicore + SIMD.
    // --------------------------------------------------------------------

    Target target = get_jit_target_from_environment();
    const int vec_width = natural_vector_size(type_of<num_t>(), target);

    // -------- Schedule for E = A * B (size nj x ni) --------
    {
        // Split variable names specific to E's update stage.
        Var j_outer_E("j_outer_E"), j_inner_E("j_inner_E");

        // Pure stage (initialization E(j,i) = 0): parallelize across rows i,
        // and vectorize across columns j (x dimension).
        E.compute_root()
         .parallel(i)
         .vectorize(j, vec_width);

        // Update stage (matrix multiply):
        // Default loop nest (conceptually) is:
        //   for i:
        //     for j:
        //       for rAB:
        //         E(j,i) += A(rAB,i) * B(j,rAB)
        //
        // Reorder to:
        //   for i:
        //     for rAB:
        //       for j:
        //         ...
        //
        // so that for a fixed (i, rAB), we walk j contiguously, improving
        // locality for B(j, rAB). Then split and vectorize j.
        E.update()
         .reorder(j, rAB, i)                // j innermost, then rAB, then i
         .split(j, j_outer_E, j_inner_E, vec_width)
         .reorder(j_inner_E, rAB, j_outer_E, i)
         .parallel(i)
         .vectorize(j_inner_E);
    }

    // -------- Schedule for F = C * D (size nl x nj) --------
    {
        Var l_outer_F("l_outer_F"), l_inner_F("l_inner_F");

        // Pure stage: parallelize rows j, vectorize cols l.
        F.compute_root()
         .parallel(j)
         .vectorize(l, vec_width);

        // Update stage:
        // Conceptual default:
        //   for j:
        //     for l:
        //       for rCD:
        //         F(l,j) += C(rCD,j) * D(l,rCD)
        //
        // Reorder so that for a fixed (j, rCD) we sweep l contiguously:
        F.update()
         .reorder(l, rCD, j)                // l innermost
         .split(l, l_outer_F, l_inner_F, vec_width)
         .reorder(l_inner_F, rCD, l_outer_F, j)
         .parallel(j)
         .vectorize(l_inner_F);
    }

    // -------- Schedule for G = E * F (size nl x ni) --------
    {
        Var l_outer_G("l_outer_G"), l_inner_G("l_inner_G");

        // Pure stage: parallelize rows i, vectorize cols l.
        G_func.compute_root()
              .parallel(i)
              .vectorize(l, vec_width);

        // Update stage:
        // Conceptual default:
        //   for i:
        //     for l:
        //       for rEF:
        //         G(l,i) += E(rEF,i) * F(l,rEF)
        //
        // Reorder so that for a fixed (i, rEF) we sweep l contiguously:
        G_func.update()
              .reorder(l, rEF, i)           // l innermost
              .split(l, l_outer_G, l_inner_G, vec_width)
              .reorder(l_inner_G, rEF, l_outer_G, i)
              .parallel(i)
              .vectorize(l_inner_G);
    }

    // Compile the kernel to machine code ahead of timing, so JIT
    // compilation time is not included in the benchmark.
    G_func.compile_jit(target);

    // Measure execution time (kernel only).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize G_func into Buffer G (shape nl x ni).
    G_func.realize(G);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix G to stderr.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // G[ii][jj] in C => G(jj, ii) in Halide
                std::cerr << G(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout with 6 decimal places,
    // matching the style of the gemm.cpp example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
