    const int vec = target.natural_vector_size(type_of<num_t>());

    // A: A(k, i)  -> parallelize over i, vectorize over k
    init_A
        .compute_root()
        .parallel(i)
        .vectorize(k, vec);

    // B: B(j, k)  -> parallelize over k, vectorize over j
    init_B
        .compute_root()
        .parallel(k)
        .vectorize(j, vec);

    // C: C(m, j)  -> parallelize over j, vectorize over m
    init_C
        .compute_root()
        .parallel(j)
        .vectorize(m, vec);

