    // Scheduling
    //
    // We keep the mathematical structure identical to the original C
    // kernel (three consecutive GEMMs) but add:
    //  - parallelism across independent rows/columns
    //  - vectorization along contiguous dimensions
    //  - loop order chosen to give good memory access for A/B/C/D
    //
    // Layout recap:
    //   A_param(k, i): k contiguous (x), i strided (y)
    //   B_param(j, k): j contiguous (x), k strided (y)
    //   C_param(m, j): m contiguous (x), j strided (y)
    //   D_param(l, m): l contiguous (x), m strided (y)
    //
    //   E(j, i): j contiguous  (x), i strided (y)  -> vectorize j
    //   F(l, j): l contiguous  (x), j strided (y)  -> vectorize l
    //   G(l, i): l contiguous  (x), i strided (y)  -> vectorize l
    //
    // For each GEMM we:
    //   - parallelize over the outer "row" dimension (i or j)
    //   - keep the reduction innermost in the scalar loop nest
    //   - vectorize the contiguous x dimension (j or l)
    // ------------------------------------------------------------------

    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());

