    // Conceptual C-like order:
    //   for i in 0..ni-1 (parallel)
    //     for k in 0..nk-1
    //       for j in 0..nj-1 (vectorized, contiguous in memory)
    //
    // This reuses A(rAB, i) across the inner j-loop and streams B(j, rAB).
    E
        .compute_root()
        .reorder(j, i)        // j is x / innermost
        .parallel(i)          // each row of E is independent
        .vectorize(j, vec);   // contiguous j

    E.update()
        .reorder(j, rAB, i)   // i outer, then reduction k, j innermost
        .parallel(i)          // rows of E are independent
        .vectorize(j, vec);   // vectorize across contiguous j

    // Schedule for F = C * D
    // Conceptual C-like order:
    //   for j in 0..nj-1 (parallel)
    //     for k in 0..nm-1
    //       for l in 0..nl-1 (vectorized, contiguous)
    F
        .compute_root()
        .reorder(l, j)
        .parallel(j)
        .vectorize(l, vec);

    F.update()
        .reorder(l, rCD, j)   // j outer, k middle, l inner
        .parallel(j)          // rows of F (over j) independent
        .vectorize(l, vec);   // contiguous l

    // Schedule for G = E * F
    // Conceptual C-like order:
    //   for i in 0..ni-1 (parallel)
    //     for k in 0..nj-1
    //       for l in 0..nl-1 (vectorized, contiguous)
    //
    // This streams one row of E (E(k, i)) and one column of F (F(l, k))
    // per output row i, accumulating into G(l, i).
    G_func
        .compute_root()
        .reorder(l, i)
        .parallel(i)
        .vectorize(l, vec);

    G_func.update()
        .reorder(l, rEF, i)   // i outer, k middle, l inner
        .parallel(i)          // rows of G (over i) independent
        .vectorize(l, vec);   // contiguous l

    // Compile the kernel to machine code with the chosen target.
    G_func.compile_jit(target);

    // Measure execution time (kernel only).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize G_func into Buffer G (shape nl x ni).
    G_func.realize(G);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix G to stderr.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // G[ii][jj] in C => G(jj, ii) in Halide
                std::cerr << G(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout with 6 decimal places,
    // matching the style of the gemm.cpp example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
