    const int vec = target.natural_vector_size(type_of<num_t>());

    init_A.compute_root()
          .reorder(k, i)          // k (x) fastest
          .vectorize(k, vec)
          .parallel(i);

    init_B.compute_root()
          .reorder(j, k)
          .vectorize(j, vec)
          .parallel(k);

