    // C: G[ni][nl] = sum_{k=0..nj-1} E[i][k] * F[k][j]
    // Halide: G_func(l, i) with x=l (col), y=i (row)
    Func G_func("G");
    G_func(l, i) = cast<num_t>(0);
    G_func(l, i) += E(rEF, i) * F(l, rEF);

    // ------------------------------------------------------------------
    // Optimized schedule
    // ------------------------------------------------------------------

    // Target and tuning knobs. These can be adjusted to tune for a
    // particular machine (e.g. cache size, vector width).
    Target target = get_host_target();
    const int vector_width = target.natural_vector_size(type_of<num_t>());

    // Tile sizes for the final GEMM (G = E * F). These affect cache
    // behavior but not correctness.
    const int tile_i = 32;  // tile size in the ni (row) dimension
    const int tile_l = 32;  // tile size in the nl (col) dimension

    // -----------------
    // Schedule for E = A * B  (shape: E(nj, ni), x=j, y=i)
    // -----------------
    //
    // Access pattern in the update:
    //   E(j, i) += A(rAB, i) * B(j, rAB)
    // We want:
    //   - j (x) to be innermost and vectorized (contiguous in memory)
    //   - i (y) to be parallelized across cores
    //
    // This mirrors a loop nest like:
    //   for i
    //     for rAB
    //       for j (vectorized)
    E.compute_root();
    E.reorder(j, i)
     .vectorize(j, vector_width)
     .parallel(i);

    E.update()
     .reorder(j, rAB, i)
     .vectorize(j, vector_width)
     .parallel(i);

    // -----------------
    // Schedule for F = C * D  (shape: F(nl, nj), x=l, y=j)
    // -----------------
    //
    // Access pattern in the update:
    //   F(l, j) += C(rCD, j) * D(l, rCD)
    // Similar strategy:
    //   - l (x) innermost and vectorized
    //   - j (y) parallel
    F.compute_root();
    F.reorder(l, j)
     .vectorize(l, vector_width)
     .parallel(j);

    F.update()
     .reorder(l, rCD, j)
     .vectorize(l, vector_width)
     .parallel(j);

    // -----------------
    // Schedule for G = E * F  (shape: G(nl, ni), x=l, y=i)
    // -----------------
    //
    // Access pattern in the update:
    //   G(l, i) += E(rEF, i) * F(l, rEF)
    //
    // For good locality:
    //   - We tile (l, i) into blocks of size (tile_l, tile_i).
    //   - Tiles are processed in parallel.
    //   - Inside each tile we keep l (x) innermost and vectorized.
    //
    // This corresponds roughly to:
    //   for each tile_index in parallel
    //     for each ii in tile of i
    //       for each k (rEF)
    //         for each li in tile of l (vectorized)
    Var lo("lo"), li("li"), io("io"), ii("ii"), tile_index("tile_index");

    // Pure initialization of G to zero.
    G_func.compute_root();
    G_func
        .tile(l, i, lo, io, li, ii, tile_l, tile_i)
        .fuse(lo, io, tile_index)
        .parallel(tile_index)
        .vectorize(li, vector_width);

    // Reduction update: same tiling, with reduction over rEF inside.
    G_func.update()
        .tile(l, i, lo, io, li, ii, tile_l, tile_i)
        .fuse(lo, io, tile_index)
        // Inner-to-outer loop order: li (vectorized) -> rEF -> ii -> tile_index
        .reorder(li, rEF, ii, tile_index)
        .parallel(tile_index)
        .vectorize(li, vector_width);

    // Compile the kernel to machine code for the host target.
    G_func.compile_jit(target);

    // Measure execution time (kernel only).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize G_func into Buffer G (shape nl x ni).
    G_func.realize(G);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix G to stderr.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // G[ii][jj] in C => G(jj, ii) in Halide
                std::cerr << G(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout with 6 decimal places,
    // matching the style of the gemm.cpp example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
