    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // Vars and reduction domains.
    Var i("i"), j("j"), l("l");
    RDom rAB(0, nk, "rAB");  // reduction over k for E = A * B
    RDom rCD(0, nm, "rCD");  // reduction over k for F = C * D
    RDom rEF(0, nj, "rEF");  // reduction over k for G = E * F

    // Define Funcs for the three matrix multiplications.
    //
    // 1) E := A * B
    // C: E[ni][nj] = sum_{k=0..nk-1} A[i][k] * B[k][j]
    // Halide: E(j, i) (x = j, y = i)
    Func E("E");
    E(j, i) = cast<num_t>(0);
    E(j, i) += A_param(rAB, i) * B_param(j, rAB);

    // 2) F := C * D
    // C: F[nj][nl] = sum_{k=0..nm-1} C[i][k] * D[k][j]
    // Halide: F(l, j) (x = l, y = j)
    Func F("F");
    F(l, j) = cast<num_t>(0);
    F(l, j) += C_param(rCD, j) * D_param(l, rCD);

    // 3) G := E * F
    // C: G[ni][nl] = sum_{k=0..nj-1} E[i][k] * F[k][j]
    // Halide: G_func(l, i) (x = l, y = i)
    Func G_func("G");
    G_func(l, i) = cast<num_t>(0);
    G_func(l, i) += E(rEF, i) * F(l, rEF);

    // ------------------------------------------------------------------
    // Scheduling
    //
    // Goal:
    //   - Keep the mathematical structure identical to the C version
    //     (compute E, F, then G) to preserve numerical behavior.
    //   - Improve data locality and use SIMD and multi-threading.
    //
    // Strategy:
    //   - Treat each matmul as an independent stage computed at root.
    //   - Parallelize the outer (row) dimension.
    //   - Vectorize the inner (column / x) dimension, which is
    //     contiguous in memory in our layout.
    //   - For the reduction updates, reorder loops so the vectorized
    //     dimension is innermost, then apply the same parallel +
    //     vectorize strategy.
    // ------------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size<num_t>();

    // ---- Schedule for E(j, i) = A * B ----
    {
        // Pure step: initialize E(j, i) = 0;
        // j is the fast (x) dimension, i is slow (y).
        E.compute_root()
         // Ensure innermost -> outermost order is (j, i):
         .reorder(j, i)
         // Parallel over rows (i), vectorize over columns (j).
         .parallel(i)
         .vectorize(j, vec_width);

        // Update step: E(j, i) += A(rAB, i) * B(j, rAB);
        // Reorder so that j is innermost, then rAB, then i.
        //   for i (parallel)
        //     for rAB
        //       for j (vectorized)
        E.update()
         .reorder(j, rAB, i)
         .parallel(i)
         .vectorize(j, vec_width);
    }

    // ---- Schedule for F(l, j) = C * D ----
    {
        // Pure step: initialize F(l, j) = 0;
        // l is fast (x), j is slow (y).
        F.compute_root()
         .reorder(l, j)
         // Parallelize across rows (j), vectorize across columns (l).
         .parallel(j)
         .vectorize(l, vec_width);

        // Update step: F(l, j) += C(rCD, j) * D(l, rCD);
        //   for j (parallel)
        //     for rCD
        //       for l (vectorized)
        F.update()
         .reorder(l, rCD, j)
         .parallel(j)
         .vectorize(l, vec_width);
    }

    // ---- Schedule for G(l, i) = E * F ----
    {
        // Pure step: initialize G(l, i) = 0;
        // l is fast (x), i is slow (y).
        G_func.compute_root()
              .reorder(l, i)
              // Parallel rows of the final result, vectorize columns.
              .parallel(i)
              .vectorize(l, vec_width);

        // Update step: G(l, i) += E(rEF, i) * F(l, rEF);
        //   for i (parallel)
        //     for rEF
        //       for l (vectorized)
        G_func.update()
              .reorder(l, rEF, i)
              .parallel(i)
              .vectorize(l, vec_width);
    }

    // Compile the kernel to machine code for the chosen target.
    G_func.compile_jit(target);

    // Measure execution time (kernel only).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize G_func into Buffer G (shape nl x ni).
    G_func.realize(G);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix G to stderr.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // G[ii][jj] in C => G(jj, ii) in Halide
                std::cerr << G(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout with 6 decimal places,
    // matching the style of the gemm.cpp example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
